{
  "claims": [
    {
      "anchor": "Once gc.auto or gc.autoPackLimit triggers housekeeping, the other tasks such as reflog and rerere pruning run as well.",
      "claim_text": "When housekeeping is triggered by exceeding gc.auto or gc.autoPackLimit limits, all other housekeeping tasks such as rerere, working trees, and reflog are performed as well.",
      "kind": "direct",
      "sure": true,
      "evidence": [
        {"sid": "P0.S0", "rel": "entails"}
      ],
      "check": null,
      "reasoning": "P0.S0 states this directly."
    },
    {
      "anchor": "With gc.auto set to 0, git gc --auto never consolidates packs, whatever gc.autoPackLimit says.",
      "claim_text": "Setting gc.auto to 0 disables pack consolidation by git gc --auto regardless of gc.autoPackLimit.",
      "kind": "logic",
      "sure": true,
      "evidence": [
        {"sid": "P2.S0", "rel": "entails"},
        {"sid": "P3.S3", "rel": "entails"}
      ],
      "check": null,
      "reasoning": "P2.S0 disables all heuristics including gc.autoPackLimit; P3.S3 confirms."
    },
    {
      "anchor": "gc.bigPackThreshold, which defaults to 1 GB",
      "claim_text": "gc.bigPackThreshold defaults to 1 GB.",
      "kind": "direct",
      "sure": true,
      "evidence": [
        {"sid": "P4.S2", "rel": "refutes"}
      ],
      "check": null,
      "reasoning": "P4.S2 says it defaults to zero, not 1 GB."
    },
    {
      "anchor": "keeps every non-cruft pack above the limit",
      "claim_text": "gc.bigPackThreshold keeps all non-cruft packs larger than the limit.",
      "kind": "direct",
      "sure": true,
      "evidence": [
        {"sid": "P4.S0", "rel": "entails"}
      ],
      "check": null,
      "reasoning": "P4.S0 states this."
    },
    {
      "anchor": "it is ignored when the number of kept packs exceeds gc.autoPackLimit",
      "claim_text": "gc.bigPackThreshold is ignored if the number of kept packs is more than gc.autoPackLimit.",
      "kind": "direct",
      "sure": true,
      "evidence": [
        {"sid": "P5.S0", "rel": "entails"}
      ],
      "check": null,
      "reasoning": "P5.S0 states this."
    },
    {
      "anchor": "which defaults to 50",
      "claim_text": "gc.autoPackLimit defaults to 50.",
      "kind": "direct",
      "sure": true,
      "evidence": [
        {"sid": "P3.S1", "rel": "entails"}
      ],
      "check": null,
      "reasoning": "P3.S1 states the default is 50."
    },
    {
      "anchor": "If gc.bigPackThreshold is not set and the memory git repack needs is not available, the largest pack is excluded from repacking.",
      "claim_text": "If the memory estimated for git repack is not available and gc.bigPackThreshold is not set, the largest pack is excluded.",
      "kind": "direct",
      "sure": true,
      "evidence": [
        {"sid": "P6.S0", "rel": "entails"}
      ],
      "check": null,
      "reasoning": "P6.S0 states this."
    },
    {
      "anchor": "When cruft packs are used, both the prune step and the cruft expiration use a two-week grace period by default.",
      "claim_text": "When cruft packs are used, prune --expire and repack --cruft --cruft-expiration both default to 2.weeks.ago.",
      "kind": "direct",
      "sure": true,
      "evidence": [
        {"sid": "P7.S0", "rel": "entails"}
      ],
      "check": null,
      "reasoning": "P7.S0 states both use 2.weeks.ago."
    },
    {
      "anchor": "Setting gc.pruneExpire to now removes that grace period",
      "claim_text": "Setting gc.pruneExpire to now disables the grace period.",
      "kind": "direct",
      "sure": true,
      "evidence": [
        {"sid": "P7.S2", "rel": "entails"}
      ],
      "check": null,
      "reasoning": "P7.S2 states 'now' disables the grace period."
    },
    {
      "anchor": "which raises the risk of corruption when another process is writing to the repository",
      "claim_text": "Pruning immediately with gc.pruneExpire=now increases the risk of corruption if another process is writing to the repository concurrently.",
      "kind": "direct",
      "sure": true,
      "evidence": [
        {"sid": "P8.S1", "rel": "entails"}
      ],
      "check": null,
      "reasoning": "P8.S1 states this risk for --prune=now."
    }
  ]
}
